const C=FormaCore,K=FormaKnowledge,E=MeshEngine,{$,esc,icon,toast,clamp,CAT,REGIONS,Bus,uid,tick}=C;
const ORIGINAL_HTML='<!doctype html>\n'+document.documentElement.outerHTML;
const byId=(id)=>id==null||id===''?null:r.objects.find(o=>o.id===Number(id));
