function notesHTML(o){return `<section class="article-section"><h3>我的观察笔记</h3><p>记录定向方法、易混点及需要回看教材的问题。笔记不发送给 Agent。</p></section><textarea id="structure-note" class="notes-area" rows="10" maxlength="20000" placeholder="例如：从后面观辨认鹰嘴窝，再转到前面比较冠突窝…"></textarea><div id="note-status" class="saved-note">仅在当前浏览器保存</div><div class="row wrap"><button class="btn" data-action="export-records">${icon('download')}备份记录</button><button class="btn" data-action="import-records">${icon('upload')}恢复记录</button></div>`;}
function jointParts(j=state.joint){if(!j)return[];const side=state.jointSide,sel=K.cardFor(current()||{})?.id;let levels=[];if(j.id==='spine'){const m=(sel||'L4').match(/^([CTL])(\d+)$/);if(m){const n=Number(m[2]),max={C:7,T:12,L:5}[m[1]];levels=[m[1]+n,m[1]+(n<max?n+1:n-1)];}}
 return j.parts.map(p=>{let arr=objects().filter(o=>{if(K.side(o)&&K.side(o)!==side)return false;const id=K.cardFor(o)?.id;if(p.ids){if(j.id==='spine'&&!p.ids.length)return levels.includes(id)&&(o.category==='skeletal'||o.category==='other');return p.ids.includes(id)&&(o.category===p.cat||o.category==='other');}return(o.category===p.cat||o.category==='other')&&p.terms.some(t=>K.norm(o.sourceName).includes(K.norm(t)));}); // Soft-tissue matches remain name candidates, never certified attachment mapping.
 if(j.id==='spine'&&!p.ids){const selected=objects().filter(o=>levels.includes(K.cardFor(o)?.id));if(selected.length){const b=E.boundsEmpty();for(const o of selected){E.boundsAdd(b,o.bounds.min);E.boundsAdd(b,o.bounds.max);}const center=E.boundsCenter(b),radius=E.Vec.length(E.boundsSize(b));arr=arr.filter(o=>E.Vec.length(E.Vec.sub(o.center,center))<radius*1.5);}}
 return{...p,objects:arr};});}
function jointLibrary(){modal('关节学习',`<p class="modal-lead">从骨面配对开始，逐项显示相关结构。模型存在的部分才会进入三维场景。</p><div class="joint-library">${K.JOINTS.map(j=>`<button class="joint-card" data-joint="${j.id}"><span class="joint-icon">${icon('joint')}</span><span class="eyebrow">${j.en}</span><h3>${j.zh}</h3><span class="pill">${j.type}</span><p>${esc(j.memory)}</p><span class="text-btn">进入学习 ${icon('arrow-right')}</span></button>`).join('')}</div>`,null,true);}
function openJoint(id){const j=K.JOINTS.find(x=>x.id===id);if(!j)return;closeModal();if(state.quiz)endQuiz();pushScene(j.zh);remember();removeTransients();resetMotion();state.panorama=null;state.joint=j;state.jointSide=K.side(current()||{})||state.jointSide;state.jointStep=-1;r.explode=0;r.clipAxis=-1;r.clearPatch();const arr=jointParts(j).flatMap(p=>p.objects);r.highlighted=new Set(arr.map(o=>o.id));r.isolated=arr.length?new Set(arr.map(o=>o.id)):null;for(const o of arr){o.hidden=false;r.catVisible[o.category]=true;}r.explodeCenter=groupCenter(arr);if(arr.length)r.fit(arr);else toast('当前未载入匹配结构：仍可阅读关节知识，或添加骨骼及关节模型');setTab('learn');syncControls();refresh();}
function jointDetail(){const j=state.joint,ps=jointParts(),n=new Set(ps.flatMap(p=>p.objects.map(o=>o.id))).size;return `<div class="detail-heading"><div class="detail-eyebrow">JOINT STUDY <span> / 连接与运动</span></div><h2>${j.zh}</h2><p class="english">${j.en}</p>${K.pinyin(j.zh)?`<p class="detail-pinyin" lang="zh-Latn">${esc(K.pinyin(j.zh))}</p>`:''}<div class="row wrap"><span class="pill ok">${j.type}</span><span class="pill">${n} 个已匹配源对象</span></div><div class="segmented joint-side"><button data-joint-side="L" class="${state.jointSide==='L'?'active':''}">左侧 / 未分侧</button><button data-joint-side="R" class="${state.jointSide==='R'?'active':''}">右侧 / 未分侧</button></div></div><div class="detail-body"><p class="detail-summary">${esc(j.body)}</p><section class="article-section"><h3>01 <span>逐项认识组成</span></h3><p>点击一行高亮对应源对象；骨面未单独标注时，高亮的是整块骨。</p></section><div class="joint-parts">${ps.map((p,i)=>`<button class="joint-part ${state.jointStep===i?'selected':''}" data-joint-part="${i}" ${p.objects.length?'':'disabled'}><span class="part-index">${String(i+1).padStart(2,'0')}</span><span><b>${esc(p.zh)}</b>${K.pinyin(p.zh)?`<i class="term-pinyin">${esc(K.pinyin(p.zh))}</i>`:''}<small>${p.objects.length?p.objects.length+' 个'+(p.ids?'整骨对象':'源名称候选'):'尚未加载 / 尚无匹配对象'}</small></span>${icon(p.objects.length?'eye':'minus')}</button>`).join('')}</div><div class="row wrap"><button class="btn" data-action="joint-next">${icon('arrow-right')}下一组成</button><button class="btn" data-action="joint-all">全部组成</button><button class="btn" data-load="joints">载入软组织</button></div><section class="article-section"><h3>02 <span>连接与运动</span></h3><p>${esc(j.motion)}</p></section><div class="mnemonic">${icon('sparkle')}<div><strong>记忆顺序</strong><p>${esc(j.memory)}</p></div></div><section class="article-section"><h3>03 <span>观察性爆炸图</span></h3><p>拖动底部“爆炸图”可分开已加载组成，归零后恢复原位。单个骨内的细部需在全景中先建立面域。</p></section><details class="motion-controls" ${state.axisPicking||state.axisPoints.length?'open':''}><summary>${icon('rotate')}手动轴运动演示 ${icon('chevron')}</summary><div><p>选两个真实表面点定义旋转轴，再选择移动骨。仅作人工设轴的刚体演示，不是自动关节中心、正常活动范围或生物力学验证。</p><button class="btn full" data-action="axis-pick">${icon('cursor')}${state.axisPoints.length===2?'重新设置':'点选'}旋转轴两点</button><div class="axis-indicator">${state.axisPoints.length===2?'两点已记录 · 可拖动角度':state.axisPicking?'在画布点选第 '+(state.axisPoints.length+1)+' 个点':'尚未定义轴'}</div><div class="moving-list">${ps.filter(p=>p.ids).flatMap(p=>p.objects).map(o=>`<label class="check-row"><input type="checkbox" data-moving="${o.id}" ${state.moving.has(o.id)||!state.moving.size&&j.moving.includes(K.cardFor(o)?.id)?'checked':''}>${esc(K.title(o))}</label>`).join('')}</div><label class="range-label">演示角度 <input id="motion-angle" type="range" min="-90" max="90" value="${state.motionAngle}" ${state.axisPoints.length===2?'':'disabled'}><output id="motion-value">${state.motionAngle}°</output></label><button class="btn" data-action="motion-reset">恢复源姿态</button></div></details><div class="detail-bottom-actions"><button class="btn" data-action="practice">${icon('quiz')}关节相关练习</button><button class="btn" data-action="scene-back">返回结构</button></div><details class="source-note"><summary>学习资料与边界</summary>${sourcesHTML(j.sources)}<p>名称匹配不证明位置关系已审校。跨模型的坐标、单位与侧别需要核对；缺失结构不会自动生成。</p></details></div>`;}
function highlightJoint(i){const ps=jointParts(),p=ps[i];if(!p?.objects.length)return toast('该组成尚无已加载的源对象');state.jointStep=i;r.highlighted=new Set(p.objects.map(o=>o.id));r.selected=-1;r.dirty=true;renderDetail();}
