function sourceModal(){modal('来源与许可',`<section class="article-section"><h3>模型不是本工作台生成的扫描</h3><p>${esc(C.ATTRIBUTION.model)}</p><p>${esc(C.ATTRIBUTION.adaptation)}</p><p>${esc(C.ATTRIBUTION.license)}</p><a href="${C.ATTRIBUTION.url}" target="_blank" rel="noopener noreferrer">上游署名与许可说明 ↗</a></section><section class="article-section"><h3>当前已加载的源文件</h3>${assets.assets.map(a=>`<div class="source-asset"><b>${esc(a.filename)}</b><p>${esc(a.quality)}</p><small>${a.objects} 对象 · ${a.triangles.toLocaleString()} 三角面 · ${C.bytes(a.bytes)}</small><code>${a.sha256}</code><p>${esc(a.license)}</p></div>`).join('')||'<p>当前没有加载资产，不能声称包含任何离线解剖数据。</p>'}</section><section class="article-section"><h3>本地学习资料索引</h3><p>提纲沿用本项目的学习数据并补充结构化解释；未经逐条医学审校。以下教材链接用于核对，不代表这些机构认证了模型。</p>${K.sources.map(s=>`<a class="source-link" href="${esc(C.safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join('')}</section><div class="notice">只有表面网格时，无法自动得出真实内部骨小梁、CT 断层或全部精细结构边界。高面数、按钮可用及名称匹配均不等于医学审校。</div>`,`<button class="btn" data-action="export-manifest">导出来源清单</button><span class="grow"></span><button class="btn" data-action="modal-close">关闭</button>`,true);}
function help(){modal('观察与学习操作',`<div class="shortcuts">${[['鼠标拖动','旋转源模型'],['G / 手形工具','平移画布'],['滚轮 / ＋ −','放大或缩小'],['双击真实表面','以点击位置为中心局部放大'],['B / 框选工具','框出区域并放大'],['右键结构','全景、聚焦、隔离与相关关节'],['F / I / Delete','聚焦、隔离、隐藏'],['Shift + F','原生全屏；失败时明确进入沉浸模式'],['L / R','标签开关 / 适应可见模型'],['Ctrl / Cmd + Z','撤销视图和可见性操作'],['拖动点阵把手','移动讲解面板或画布工具栏'],['面板边缘','调整停靠面板宽度']].map(([k,v])=>`<div class="shortcut"><kbd>${esc(k)}</kbd><span>${esc(v)}</span></div>`).join('')}</div><section class="article-section"><h3>学习闭环</h3><p>结构树定位 → 右键全景 → 细部术语与面域观察 → 连接中的关节学习 → 练习。退出局部场景和练习后可以回到原来的视图。</p></section><section class="article-section"><h3>骨内细部与关节运动</h3><p>完整源骨不会被随意切碎。细部展开需要先在真实表面保存面域。运动工具由你设轴，属于刚体教学演示，不提供自动准确关节轴或正常活动范围。</p></section><p class="micro-note">全屏时面板默认隐藏，右上角可临时显示画布工具；Esc 退出。源坐标轴与解剖学方向必须由模型来源确认。</p>`,null,true);}
async function fullscreen(){hideMenus();if(document.fullscreenElement){await document.exitFullscreen();return;}if(document.body.classList.contains('immersive')){document.body.classList.remove('immersive','show-full-tools');return;}try{if(!document.documentElement.requestFullscreen)throw Error('not supported');await document.documentElement.requestFullscreen();document.body.classList.add('immersive');$('full-tools').querySelector('span').textContent='退出全屏';}catch{document.body.classList.add('immersive');$('full-tools').querySelector('span').textContent='退出沉浸';toast('浏览器未允许原生全屏：当前是隐藏面板的沉浸模式，地址栏可能仍在');}r.dirty=true;}
function recordPack(){return{format:'forma-learning-records-v3',version:3,exportedAt:new Date().toISOString(),notes:state.notes,patches:state.patches,favorites:[...state.favorites],quizHistory:state.quizHistory,views:state.views};}
function importRecords(pack){if(!pack||typeof pack!=='object')throw Error('记录数据无效');if(pack.notes&&typeof pack.notes==='object')for(const[k,v]of Object.entries(pack.notes)){if(k.length>500||typeof v!=='string'||v.length>20000||['__proto__','constructor','prototype'].includes(k))continue;state.notes[k]=v;}if(Array.isArray(pack.patches))for(const p of pack.patches){if(!p||!Array.isArray(p.faces)||p.faces.length>5000000||!p.faces.every(n=>Number.isSafeInteger(n)&&n>=0)||!Number.isSafeInteger(p.partIndex)||p.partIndex<0)continue;const a={id:String(p.id||uid()),label:String(p.label||p.name||'导入面域').slice(0,100),assetSHA256:String(p.assetSHA256||p.assetSha256||p.assetSHA||''),sourceName:String(p.sourceName||''),nodeIndex:p.nodeIndex,objectKey:String(p.objectKey||p.key||''),partIndex:p.partIndex,sourceTriangles:p.sourceTriangles,legacyObjectTriangles:p.legacyObjectTriangles??(p.assetSHA&&!p.assetSHA256?p.sourceTriangles:undefined),faces:p.faces,center:Array.isArray(p.center)?p.center.slice(0,3):null,status:'user_annotation_unreviewed',createdAt:p.createdAt};if(!state.patches.some(x=>x.id===a.id))state.patches.push(a);}
 if(Array.isArray(pack.favorites))for(const k of pack.favorites)if(typeof k==='string'&&k.length<500)state.favorites.add(k);if(Array.isArray(pack.quizHistory))state.quizHistory=[...state.quizHistory,...pack.quizHistory.filter(x=>x&&Number.isFinite(x.score)&&Number.isFinite(x.total))].slice(-100);if(Array.isArray(pack.views))state.views=[...state.views,...pack.views].slice(-12);save();refresh();}
async function exportOffline(){if(!assets.assets.length)throw Error('还没有实际模型数据。先载入源模型，再导出含模型的离线 HTML。');toast('正在把已载入的真实数据写入 HTML；密钥与对话不会加入');await tick();const packaged=[];for(const a of assets.assets){const{buffer,...meta}=a;packaged.push({...meta,embedded:true,data:C.b64encode(buffer)});await tick();}const data={...recordPack(),version:3,assets:packaged,view:persistView(),theme:state.theme};const json=JSON.stringify(data).replace(/</g,'\\u003c');const start='<!--ASSET_PAYLOAD_BEGIN-->',end='<!--ASSET_PAYLOAD_END-->';const i=ORIGINAL_HTML.indexOf(start),j=ORIGINAL_HTML.indexOf(end,i);if(i<0||j<0)throw Error('导出模板插槽不存在');const html=ORIGINAL_HTML.slice(0,i)+start+'<script id="payload-data" type="application/json">'+json+'</scr'+'ipt>'+ORIGINAL_HTML.slice(j);C.saveFile(new Blob([html],{type:'text/html;charset=utf-8'}),'forma_anatomy_offline.html');toast('已导出 '+packaged.length+' 个实际资产；未加载的系统不包含在内');}
function persistView(){return{camera:cameraState(),selected:current()?objectKey(current()):null,hidden:objects().filter(o=>o.hidden).map(objectKey),isolated:r.isolated?objects().filter(o=>r.isolated.has(o.id)).map(objectKey):null,catVisible:{...r.catVisible},catAlpha:{...r.catAlpha},explode:r.explode,clipAxis:r.clipAxis,clipFraction:r.clipFraction,clipSign:r.clipSign};}
function loadView(v){if(!v?.camera||!Array.isArray(v.camera.target)||!v.camera.target.every(Number.isFinite))throw Error('视图记录无效');remember();removeTransients();resetMotion();r.clearPatch();const c=v.camera;if(![c.span,c.yaw,c.pitch].every(Number.isFinite)||c.span<=0)throw Error('相机数据无效');Object.assign(r,{target:c.target.slice(0,3),yaw:c.yaw,pitch:clamp(c.pitch,-1.57,1.57),span:c.span,perspective:!!c.perspective});const h=new Set(v.hidden||[]),is=v.isolated?new Set(v.isolated):null;for(const o of objects())o.hidden=h.has(objectKey(o));r.isolated=is?new Set(objects().filter(o=>is.has(objectKey(o))).map(o=>o.id)):null;r.catVisible={...v.catVisible};r.catAlpha={...v.catAlpha};r.explode=clamp(v.explode||0,0,1);r.clipAxis=[-1,0,1,2].includes(v.clipAxis)?v.clipAxis:-1;r.clipFraction=clamp(v.clipFraction??.5,0,1);r.clipSign=v.clipSign===-1?-1:1;const o=objects().find(o=>objectKey(o)===v.selected);state.selected=o?.id??null;r.selected=state.selected??-1;state.nameHint=!!state.selected;state.panorama=null;state.joint=null;r.dirty=true;syncControls();refresh();}
