async function importFiles(files){const category=$('import-category')?.value||'other';closeModal();bus.emit('loading-start');try{for(const file of files)await assets.importFile(file,category);state.panorama=null;state.joint=null;state.history=[];state.undo=[];r.isolated=null;r.explode=0;r.motion=null;r.fit();refresh();toast('本地源文件已载入');}finally{bus.emit('loading-end');$('model-files').value='';}}
function capture(){r.draw();const canvas=document.createElement('canvas');canvas.width=r.canvas.width;canvas.height=r.canvas.height;const ctx=canvas.getContext('2d');ctx.fillStyle=state.theme==='dark'?'#19231f':'#eef1ed';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(r.canvas,0,0);ctx.fillStyle=state.theme==='dark'?'#d4dfd6':'#435349';ctx.font=Math.max(12,canvas.width/85)+'px sans-serif';ctx.fillText('FORMA · '+(current()?K.title(current()):'源模型观察')+' · 学习参考 / 非临床',20,canvas.height-25);canvas.toBlob(b=>b&&C.saveFile(b,'forma_view.png'));}
function refresh(){syncScene();renderCatalog();if(state.tab==='learn')renderDetail();if(state.tab==='quiz')renderQuiz();agent?.status();r.dirty=true;}
