 'bones-only':()=>{remember();for(const c of Object.keys(CAT))r.catVisible[c]=c==='skeletal';r.isolated=null;r.fit();refresh();},
 'show-all-layers':()=>{remember();for(const c of Object.keys(CAT)){r.catVisible[c]=c!=='regions';r.catAlpha[c]=1;}for(const o of objects())o.hidden=false;r.isolated=null;r.fit();refresh();},
